import {WORLD,LAND,TYPES,WEAPONS,SCENARIOS,createState,unitById,addUnit,removeUnit,start,setRoute,formFleet,scan,visibleContacts,distance,bearing,fireCheck,fire,step,serialize,deserialize,log} from './engine.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=s=>[Math.floor(s/3600),Math.floor(s/60)%60,Math.floor(s)%60].map(n=>String(n).padStart(2,'0')).join(':');
let state=createState(),selected=state.units[0].id,target=null,tab='fleet',timeScale=30,mode=null,deploySide='blue';
let layers={sensors:true,trails:false,grid:true},lastFrame=performance.now(),lastUI=0,lastList='',lastInspector='',lastEvents='',toastTimer,draggingSlider=false;
const canvas=$('#map'),ctx=canvas.getContext('2d'),camera={x:120,y:85,zoom:1,base:1};let width=0,height=0;

// 浮层独立于海图：收放、拖动只改变组件，不触发海图缩放或重新定位。
const widgetNames={mission:'剧本',fleet:'舰队',inspector:'单位控制',view:'海图工具',log:'作战记录',time:'推演'};
let widgetDrag=null;
function frontWidget(key){$$('[data-widget]').forEach(el=>el.style.zIndex=el.dataset.widget===key?'10':'');}
function rememberWidgets(){try{localStorage.setItem('seapower-widgets-v1',JSON.stringify({...Object.fromEntries($$('[data-widget]').map(el=>[el.dataset.widget,!el.classList.contains('is-collapsed')])),dock:!$('.hud-dock').classList.contains('is-collapsed')}));}catch{}}
function syncWidgetControls(){const allCollapsed=$$('[data-widget]').every(el=>el.classList.contains('is-collapsed'));$('#collapse-all').textContent=allCollapsed?'全部展开':'全部收起';for(const el of $$('[data-widget]')){const key=el.dataset.widget,open=!el.classList.contains('is-collapsed');el.querySelector('.widget-body').inert=!open;$$(`[data-widget-toggle="${key}"]`).forEach(b=>{b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-controls',`${key}-body`);if(b.closest('.widget-heading')){b.textContent=open?'⌃':'⌄';b.setAttribute('aria-label',`${open?'收起':'展开'}${widgetNames[key]}组件`);}else{b.classList.toggle('widget-active',open);b.setAttribute('aria-label',`切换${widgetNames[key]}组件`);b.title=`${open?'收起':'展开'}${widgetNames[key]}组件`;}});}}
function clampWidget(el){if(!el.style.left)return;const r=el.getBoundingClientRect();el.style.left=`${Math.max(8,Math.min(innerWidth-r.width-8,r.left))}px`;el.style.top=`${Math.max(8,Math.min(innerHeight-r.height-8,r.top))}px`;}
function setDockOpen(open){$('.hud-dock').classList.toggle('is-collapsed',!open);$('#dock-tools').inert=!open;$('#dock-toggle').setAttribute('aria-expanded',String(open));$('#dock-toggle').setAttribute('aria-label',`${open?'收起':'展开'}组件控制台`);rememberWidgets();}
function setWidgetOpen(key,open){const el=$(`[data-widget="${key}"]`);if(!el)return;const body=el.querySelector('.widget-body');if(!open&&body.contains(document.activeElement))el.querySelector('[data-widget-toggle]').focus();el.classList.toggle('is-collapsed',!open);if(open){frontWidget(key);if(innerWidth<=650&&['fleet','inspector'].includes(key)){const other=$(`[data-widget="${key==='fleet'?'inspector':'fleet'}"]`);other.classList.add('is-collapsed');}}syncWidgetControls();clampWidget(el);rememberWidgets();}
function initializeWidgets(){let saved=null;try{saved=JSON.parse(localStorage.getItem('seapower-widgets-v1'));}catch{}for(const el of $$('[data-widget]')){const key=el.dataset.widget;const open=typeof saved?.[key]==='boolean'?saved[key]:key==='time';el.classList.toggle('is-collapsed',!open);}syncWidgetControls();if(typeof saved?.dock==='boolean')setDockOpen(saved.dock);const dockObserver=new ResizeObserver(()=>{for(const key of ['mission','view','log'])document.documentElement.style.setProperty(`--${key}-height`,`${$(`[data-widget="${key}"]`).getBoundingClientRect().height+(key==='log'&&!$('#log-widget').classList.contains('is-collapsed')?56:0)}px`);});for(const key of ['mission','view','log'])dockObserver.observe($(`[data-widget="${key}"]`));}
document.addEventListener('pointerdown',e=>{const heading=e.target.closest('[data-widget-drag]');if(!heading||e.target.closest('button')||e.button!==0)return;const key=heading.dataset.widgetDrag,el=heading.closest('[data-widget]'),r=el.getBoundingClientRect();widgetDrag={id:e.pointerId,el,heading,dx:e.clientX-r.left,dy:e.clientY-r.top};frontWidget(key);el.classList.add('is-dragging');el.style.left=`${r.left}px`;el.style.top=`${r.top}px`;el.style.right='auto';el.style.bottom='auto';el.style.transform='none';heading.setPointerCapture(e.pointerId);e.preventDefault();});
document.addEventListener('pointermove',e=>{if(!widgetDrag||e.pointerId!==widgetDrag.id)return;const {el,dx,dy}=widgetDrag,r=el.getBoundingClientRect();el.style.left=`${Math.max(8,Math.min(innerWidth-r.width-8,e.clientX-dx))}px`;el.style.top=`${Math.max(8,Math.min(innerHeight-r.height-8,e.clientY-dy))}px`;});
function endWidgetDrag(){if(widgetDrag)widgetDrag.el.classList.remove('is-dragging');widgetDrag=null;}
document.addEventListener('pointerup',endWidgetDrag);document.addEventListener('pointercancel',endWidgetDrag);
window.addEventListener('resize',()=>{for(const el of $$('[data-widget]')){if(!el.style.left)continue;const r=el.getBoundingClientRect();el.style.left=`${Math.max(8,Math.min(innerWidth-r.width-8,r.left))}px`;el.style.top=`${Math.max(8,Math.min(innerHeight-r.height-8,r.top))}px`;}});

function icon(type){const domain=TYPES[type]?.domain;return `<svg viewBox="0 0 32 32" aria-hidden="true">${domain==='air'?'<path d="M16 3v23M6 20l10-10 10 10M11 27l5-4 5 4"/>':domain==='sub'?'<path d="M5 16c2-8 20-8 22 0-2 8-20 8-22 0zM16 10V5m-4 0h8M10 24h12"/>':'<path d="M9 7h14v16H9zM16 7V2m-5 25h10M12 13h8m-4-4v8"/>'}</svg>`;}
function toast(message,error=false){$('#toast').textContent=message;$('#toast').className=`toast${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3200);}
function result(r,success){if(!r.ok)toast(r.error,true);else if(success)toast(success);lastInspector='';lastList='';renderUI();return r.ok;}
function modal(title,body){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-close aria-label="关闭窗口">×</button></div><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
function resetScenario(id){state=createState(id);selected=state.units[0]?.id;target=null;mode=null;tab='fleet';camera.zoom=1;camera.x=120;camera.y=85;lastList=lastInspector=lastEvents='';$('#dialog').close();$('#inspector').scrollTop=0;$('#inspector-body').scrollTop=0;renderUI();toast(`${SCENARIOS[id].name}已载入`);}
function setMode(next){mode=next;$('#briefing').classList.toggle('hidden',!!mode||state.phase!=='setup');const banner=$('#mode-banner');banner.classList.toggle('hidden',!mode);if(mode){banner.innerHTML=`${mode.kind==='deploy'?`部署${deploySide==='blue'?'蓝方':'红方'} ${TYPES[mode.type].name} · 点击海图放置`:'点击海域设置航点 · Shift 追加航点'}<button data-cancel-mode>取消</button>`;}canvas.style.cursor=mode?'crosshair':'default';}
function togglePlay(){if(state.phase==='setup'){if(unitById(state,selected)?.side==='red')selected=state.units.find(u=>u.side==='blue')?.id;if(result(start(state)))setMode(null);}else if(state.phase==='running'){state.paused=!state.paused;toast(state.paused?'推演暂停':'继续推演');}renderUI();}

function openDeploy(){if(state.phase!=='setup'){toast('只能在部署阶段调整编队',true);return;}modal('部署作战单位',`<p>选择平台，再点击海图放置。${state.scenario==='sandbox'?'自由沙盘支持双方部署。':'蓝方部署区位于海图西侧。'}</p>${state.scenario==='sandbox'?`<div class="side-toggle"><button data-side="blue" class="${deploySide==='blue'?'active':''}">蓝方编队</button><button data-side="red" class="${deploySide==='red'?'active':''}">红方编队</button></div>`:''}<div class="deploy-grid">${Object.entries(TYPES).map(([type,t])=>`<button class="deploy-card" data-deploy-type="${type}" ${deploySide==='blue'&&state.budget<t.cost?'disabled':''}><span class="unit-icon">${icon(type)}</span><span><strong>${t.name}</strong><small>${t.desc}</small><span class="price">${t.code} &nbsp; / &nbsp; ${t.cost} 部署点</span></span></button>`).join('')}</div><div class="dialog-bottom"><span>蓝方剩余部署点 <b>${state.budget}</b></span><span>放置后仍可撤回</span></div>`);}
function openScenarios(){modal('选择作战海域',`<p>切换剧本会重置当前推演，可先保存战局。</p>${Object.entries(SCENARIOS).map(([id,s])=>`<button data-scenario="${id}" class="scenario-card ${state.scenario===id?'active':''}"><strong>${s.name}</strong><small>${s.subtitle} · ${s.budget} 部署点<br>${s.brief}</small></button>`).join('')}`);}
function openHelp(){modal('指挥官操作指南',`<p>先部署编队，再建立接触航迹，最后选择武器交战。</p><ol class="help-list"><li><b>01 · 部署与传感器</b>点击“部署单位”，选择平台后在海图放置。选择蓝方单位，开启雷达或声呐。电子支援只能粗略定位开启雷达的目标，不能据此开火。</li><li><b>02 · 航线与编队</b>右键海域设定航点；<kbd>Shift</kbd> + 右键追加航点。也可点击“设置航线”或输入坐标。选择水面旗舰后点击“编队跟随”，其他水面舰会跟随。</li><li><b>03 · 选择目标与发射</b>先选蓝方单位，再点击红方接触或舰队组件中的“接触”列表。有效航迹、合适的目标类型、射程和弹药齐备后，点击武器旁的“发射”。</li><li><b>04 · 时间与视图</b><kbd>空格</kbd> 开始 / 暂停，<kbd>Esc</kbd> 取消指令。滚轮缩放，拖动空白海域平移。1×、10×、30×、120× 控制推演速度。</li><li><b>05 · 防空与反潜</b>开启雷达与“自动防空”后，会消耗防空弹药拦截来袭导弹。潜艇只能由声呐探测，水面舰高速航行会降低声呐探测距离。天气会影响探测范围。</li></ol><p class="tiny" style="margin-top:16px">底部控制台可展开或收起各组件；“全部收起”清空视野。拖动组件顶栏可移动位置，点击单位自动展开单位控制。组件收放状态会保存在当前浏览器。</p><div class="help-foot">本平台为虚构海域、简化参数的策略沙盘。借鉴 <a href="https://store.steampowered.com/app/1286220/" target="_blank" rel="noopener noreferrer">Sea Power</a> 的海空协同与传感器玩法，使用原创界面与海图。舰船速度以节计，距离以海里计。战局保存在当前浏览器，可导出 JSON 迁移。</div>`);}
function openLoad(){let saved=false;try{saved=!!localStorage.getItem('seapower-save-v1');}catch{}modal('载入战局',`<p>载入会替换当前战局。载入后默认暂停，点击 ▶ 继续。</p><button class="primary wide" id="load-local" ${saved?'':'disabled'}>${saved?'载入浏览器中的战局':'当前浏览器尚无存档'}</button><button class="outline wide" id="import-trigger" style="margin-top:12px">从 JSON 文件导入</button><p class="tiny" style="margin-top:18px">存档包含编队、弹药、传感器状态、航点及在途武器；不需要账号或服务器。</p>`);}
function loadText(text){try{state=deserialize(text);selected=state.units.find(u=>u.side==='blue'&&u.hp>0)?.id;target=null;setMode(null);lastList=lastInspector=lastEvents='';$('#dialog').close();renderUI();toast('战局已载入，推演暂停');}catch(e){toast(`无法载入：${e.message}`,true);}}
function exportState(){const blob=new Blob([serialize(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`SeaPower-${state.scenario}-${Math.floor(state.time)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('战局已导出');}

function renderUI(){
  $('#clock').textContent=clock(state.time);$('#play').textContent=state.phase==='running'&&!state.paused?'Ⅱ':'▶';$('#play').setAttribute('aria-label',state.phase==='running'&&!state.paused?'暂停推演':'开始推演');$('#play').disabled=state.phase==='ended';
  $('#phase').textContent=state.phase==='setup'?'部署阶段':state.phase==='ended'?'推演结束':state.paused?'推演暂停':'实时推演';$('.mission-status .dot').style.background=state.paused?'#8496a1':'#80cbb8';
  $('#scenario').innerHTML=`${SCENARIOS[state.scenario].name} <span>⌄</span>`;$('#mission-subtitle').textContent=SCENARIOS[state.scenario].subtitle;
  $('#brief-text').textContent=SCENARIOS[state.scenario].brief;$('#briefing').classList.toggle('hidden',state.phase!=='setup'||!!mode);
  $('#selection-summary').textContent=unitById(state,selected)?.name||'未选择';
  $('#weather').value=state.weather;$('#weather').disabled=state.phase==='ended';$('#deploy').disabled=state.phase!=='setup';
  const contacts=visibleContacts(state),friendlies=state.units.filter(u=>u.side==='blue'),editingRed=state.phase==='setup'&&state.scenario==='sandbox',reds=state.units.filter(u=>u.side==='red');$('#fleet-count').textContent=friendlies.filter(u=>u.hp>0).length;$('#contacts-tab').innerHTML=editingRed?`红方编队 <span id="contact-count">${reds.length}</span>`:`接触 <span id="contact-count">${contacts.length}</span>`;
  $('#budget').textContent=tab==='fleet'?`部署点 ${state.budget}`:editingRed?'预设红方':`${contacts.filter(c=>!c.stale&&c.quality==='track').length} 条有效航迹`;$('#list-heading').textContent=tab==='fleet'?'作战单位':editingRed?'红方作战单位':'探测到的接触';
  $('#fleet-tab').classList.toggle('active',tab==='fleet');$('#contacts-tab').classList.toggle('active',tab==='contacts');
  const signature=JSON.stringify([tab,selected,target,editingRed,reds.map(u=>[u.id,u.name]),friendlies.map(u=>[u.id,u.name,u.hp,u.radar,u.sonar,u.route.length,u.leader]),contacts.map(c=>[c.id,c.quality,c.stale])]);
  if(signature!==lastList){lastList=signature;$('#unit-list').innerHTML=tab==='fleet'?friendlies.map(u=>`<button class="unit-row ${u.id===selected?'selected':''} ${u.hp<=0?'destroyed':''}" data-unit="${u.id}"><span class="unit-icon">${icon(u.type)}</span><span class="unit-copy"><strong>${escape(u.name)}</strong><small>${TYPES[u.type].name}</small></span><span class="row-status ${u.hp<=0||!u.radar&&!u.sonar?'off':''}" title="${u.hp<=0?'已损失':u.radar||u.sonar?'传感器已开启':'传感器静默'}"></span></button>`).join(''):editingRed?reds.map(u=>`<button class="unit-row enemy ${u.id===selected?'selected':''}" data-unit="${u.id}"><span class="unit-icon">${icon(u.type)}</span><span class="unit-copy"><strong>${escape(u.name)}</strong><small>${TYPES[u.type].name} · 部署中</small></span></button>`).join(''):contacts.length?contacts.map(c=>`<button class="unit-row enemy ${target===c.id?'selected':''}" data-target="${c.id}"><span class="unit-icon">${icon(c.domain==='air'?'fighter':c.domain==='sub'?'submarine':'frigate')}</span><span class="unit-copy"><strong>${escape(c.label)}</strong><small>${c.source} · ${c.stale?'航迹失效':c.quality==='bearing'?'粗略定位':'有效航迹'}</small></span></button>`).join(''):'<div class="contact-empty">尚未发现接触。<br>开始推演并开启雷达，<br>或使用声呐搜索水下目标。</div>';}
  renderInspector();
  const eventSignature=JSON.stringify(state.events.slice(0,20));if(eventSignature!==lastEvents){lastEvents=eventSignature;$('#events').innerHTML=state.events.slice(0,20).map(e=>`<div class="log-row ${e.kind}"><time>${clock(e.time)}</time><span>${escape(e.message)}</span></div>`).join('');}
  $('#result').classList.toggle('hidden',state.phase!=='ended');if(state.phase==='ended'&&!$('#result').innerHTML){$('#result').innerHTML=`<span class="eyebrow">OPERATION COMPLETE</span><h2>${state.result==='victory'?'任务完成':state.result==='draw'?'双方损失':'编队损失'}</h2><p>推演时长 ${clock(state.time)}<br>蓝方存活 ${friendlies.filter(u=>u.hp>0).length} / ${friendlies.length} 个单位</p><button id="restart" class="primary">重新部署 ↗</button>`;}if(state.phase!=='ended')$('#result').innerHTML='';
}
function renderInspector(){
  const u=unitById(state,selected),c=state.contacts.blue[target];const signature=JSON.stringify([u?{...u,trail:undefined,x:Math.floor(u.x),y:Math.floor(u.y),cooldown:u.cooldown>state.time}:null,c?{...c,time:undefined,x:Math.round(c.x),y:Math.round(c.y),stale:state.time-c.time>6}:null,state.phase,state.paused]);
  if(signature===lastInspector||draggingSlider)return;const sliderFocused=document.activeElement?.id==='speed-slider';lastInspector=signature;
  if(!u){$('#inspector').innerHTML='<div class="inspector-heading">单位控制</div><p class="selection-empty">选择一个蓝方单位<br>查看传感器和武器系统。</p>';return;}
  const t=TYPES[u.type],health=Math.round(u.hp/t.hp*100),alive=u.hp>0&&state.phase!=='ended';
  $('#inspector').innerHTML=`<div class="inspector-heading"><span>单位控制</span><span class="unit-code">${t.code}</span></div><h2 class="unit-title">${escape(u.name)}</h2><div class="unit-description">${t.name} · ${t.domain==='air'?'空中平台':t.domain==='sub'?'水下平台':'水面舰艇'}</div><div class="health-row"><span>${u.hp<=0?'单位已损失':'结构完整度'}</span><b>${health}%</b></div><div class="healthbar"><div style="width:${health}%;${health<40?'background:#e88480':''}"></div></div>
    <div class="section-label"><span>传感器</span><small>SENSORS</small></div><div class="sensors">${[['radar','雷达',t.radar],['sonar','声呐',t.sonar],['esm','电子支援',t.esm]].map(([key,name,range])=>`<button data-sensor="${key}" class="sensor-btn ${u[key]&&range?'active':''}" ${!range||!alive?'disabled':''} title="${range?`${name}标称范围 ${range} nm`:'未配备'}"><i class="sensor-dot"></i>${name}</button>`).join('')}</div><p class="sensor-note">${u.radar&&t.radar?'主动雷达发射中，对方电子支援可侦知。':u.sonar&&t.sonar?'声呐搜索中，低速航行有利于探测。':'保持电磁静默，电子支援接触仅供参考。'}</p><canvas class="radar-mini" id="radar-mini" aria-label="局部传感器态势"></canvas>
    <div class="section-label"><span>航行指令</span><small>NAVIGATION</small></div><div class="speed-row"><span>${u.leader?'跟随旗舰':u.route.length?`${u.route.length} 个航点`:'待命'} · 航向 ${Math.round(u.heading)}°</span><b id="speed-value">${u.speed} kn</b></div><input type="range" id="speed-slider" min="0" max="${t.speed}" value="${u.speed}" aria-label="航行速度（节）" ${!alive?'disabled':''}><div class="command-row"><button data-command="route" ${!alive?'disabled':''}>设置航线</button><button data-command="coordinate" ${!alive?'disabled':''} title="输入航点坐标">坐标</button><button data-command="stop" ${!alive?'disabled':''}>停止</button></div>${t.domain==='surface'&&u.side==='blue'?`<button class="outline wide" data-command="formation" style="margin-top:8px;font-size:10px" ${!alive?'disabled':''}>指定旗舰 · 编队跟随</button>`:''}
    <div class="section-label"><span>武器系统</span><small>WEAPONS</small></div>${c?`<div class="target-card"><div><span>${escape(c.label)}</span><button data-clear-target aria-label="取消目标">×</button></div><small>${distance(u,c).toFixed(1)} nm · ${Math.round(bearing(u,c))}° · ${state.time-c.time>6?'失效航迹':c.quality==='track'?'有效航迹':'粗略定位'}</small></div>`:'<div class="empty-target">点击海图中的红方接触<br>或在接触列表中选择目标。</div>'}${Object.entries(WEAPONS).filter(([key])=>t.weapons[key]>0).map(([key,w])=>{const check=c?fireCheck(state,u.id,c.id,key):{ok:false,error:'请选择目标'};return `<div class="weapon-row"><div class="weapon-label">${w.name}<small>${w.short} / ${w.range} nm</small></div><span class="weapon-qty">${String(u.weapons[key]).padStart(2,'0')}</span><button class="weapon-fire" data-fire="${key}" ${check.ok?'':'disabled'} title="${check.ok?'发射一枚武器':check.error}">发射</button></div>`;}).join('')}<label class="check-row"><input type="checkbox" id="auto-defense" ${u.autoDefense?'checked':''} ${!alive||!t.weapons.sam?'disabled':''}> 自动防空拦截</label>${state.phase==='setup'?`<button class="remove-unit" data-command="remove">${u.side==='blue'?`撤回此单位 · 返还 ${t.cost} 部署点`:'撤回红方单位'}</button>`:''}<p class="tiny" style="margin-top:15px">位置 ${u.x.toFixed(1)}, ${u.y.toFixed(1)} nm<br>传感器与武器参数为策略沙盘设定。</p>`;
  if(sliderFocused)$('#speed-slider')?.focus({preventScroll:true});
}

// 事件统一委托，面板随推演更新时不重复绑定监听器。
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.widgetToggle){const key=b.dataset.widgetToggle;setWidgetOpen(key,$(`[data-widget="${key}"]`).classList.contains('is-collapsed'));}
  else if(b.id==='collapse-all'){const open=$$('[data-widget]').every(el=>el.classList.contains('is-collapsed'));for(const key of Object.keys(widgetNames))setWidgetOpen(key,open);}
  else if(b.id==='dock-toggle')setDockOpen($('.hud-dock').classList.contains('is-collapsed'));
  else if(b.hasAttribute('data-close'))$('#dialog').close();
  else if(b.dataset.speed){timeScale=Number(b.dataset.speed);$$('[data-speed]').forEach(x=>x.classList.toggle('active',x===b));}
  else if(b.dataset.layer){layers[b.dataset.layer]=!layers[b.dataset.layer];b.classList.toggle('active',layers[b.dataset.layer]);}
  else if(b.dataset.unit){selected=b.dataset.unit;$('#inspector').scrollTop=0;$('#inspector-body').scrollTop=0;setWidgetOpen('inspector',true);lastInspector='';renderUI();}
  else if(b.dataset.target){target=b.dataset.target;setWidgetOpen('inspector',true);lastInspector='';renderUI();}
  else if(b.dataset.sensor){const u=unitById(state,selected);if(u&&u.hp>0){u[b.dataset.sensor]=!u[b.dataset.sensor];log(state,`${u.name} ${b.textContent.trim()}${u[b.dataset.sensor]?'开启':'关闭'}`);if(state.phase==='running')scan(state);lastInspector='';renderUI();}}
  else if(b.dataset.fire){result(fire(state,selected,target,b.dataset.fire),'武器已发射');}
  else if(b.dataset.command){const u=unitById(state,selected);if(!u)return;const cmd=b.dataset.command;if(cmd==='route')setMode({kind:'route'});if(cmd==='stop'){u.route=[];u.leader=null;u.speed=0;log(state,`${u.name} 停止航行`);lastInspector='';renderUI();}if(cmd==='formation')result(formFleet(state,selected),'编队已建立，向旗舰下达航线');if(cmd==='remove'){if(removeUnit(state,selected)){selected=state.units.find(u=>u.side==='blue')?.id;renderUI();toast('单位已撤回');}}if(cmd==='coordinate'){modal('输入航点坐标',`<p>海图使用海里坐标。X：1–239，Y：1–169；水面与水下航线须避开陆地。</p><form id="route-form"><div class="route-coords"><label>X / 东向海里<input name="x" type="number" min="1" max="239" step="0.1" value="${u.x.toFixed(1)}" required></label><label>Y / 南向海里<input name="y" type="number" min="1" max="169" step="0.1" value="${u.y.toFixed(1)}" required></label></div><label class="check-row"><input type="checkbox" name="append">追加到当前航线</label><button type="submit" class="primary wide" style="margin-top:20px">下达航行指令</button></form>`);}}
  else if(b.dataset.deployType){$('#dialog').close();setMode({kind:'deploy',type:b.dataset.deployType});}
  else if(b.dataset.side){deploySide=b.dataset.side;openDeploy();}
  else if(b.dataset.scenario)resetScenario(b.dataset.scenario);
  else if(b.hasAttribute('data-cancel-mode'))setMode(null);
  else if(b.hasAttribute('data-clear-target')){target=null;lastInspector='';renderUI();}
  else switch(b.id){case'play':case'begin':togglePlay();break;case'deploy':deploySide='blue';openDeploy();break;case'scenario':openScenarios();break;case'help':openHelp();break;case'fleet-tab':tab='fleet';renderUI();break;case'contacts-tab':tab='contacts';renderUI();break;case'save':try{localStorage.setItem('seapower-save-v1',serialize(state));toast('战局已保存到当前浏览器');}catch{toast('浏览器无法保存，请导出 JSON 战局',true);}break;case'load':openLoad();break;case'load-local':try{loadText(localStorage.getItem('seapower-save-v1'));}catch{toast('无法访问浏览器存档',true);}break;case'import-trigger':$('#import-file').click();break;case'export':exportState();break;case'zoom-in':camera.zoom=Math.min(5,camera.zoom*1.25);break;case'zoom-out':camera.zoom=Math.max(.65,camera.zoom/1.25);break;case'zoom-fit':camera.zoom=1;camera.x=120;camera.y=85;break;case'restart':resetScenario(state.scenario);break;}
});
document.addEventListener('pointerdown',e=>{if(e.target.id==='speed-slider')draggingSlider=true;});
document.addEventListener('pointerup',()=>{draggingSlider=false;});
document.addEventListener('input',e=>{if(e.target.id==='speed-slider'){const u=unitById(state,selected);if(u){u.speed=Number(e.target.value);$('#speed-value').textContent=`${u.speed} kn`;lastInspector='';}}});
document.addEventListener('change',e=>{if(e.target.id==='auto-defense'){unitById(state,selected).autoDefense=e.target.checked;lastInspector='';}if(e.target.id==='weather'){state.weather=e.target.value;log(state,`海况调整为${state.weather==='storm'?'风暴，探测范围降低':'晴朗'}`);if(state.phase==='running')scan(state);renderUI();}});
document.addEventListener('submit',e=>{if(e.target.id==='route-form'){e.preventDefault();const form=new FormData(e.target);if(result(setRoute(state,selected,{x:Number(form.get('x')),y:Number(form.get('y'))},form.has('append')),'航行指令已下达'))$('#dialog').close();}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(f){if(f.size>250000)toast('战局文件过大',true);else loadText(await f.text());}e.target.value='';});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('#dialog').open)return;if(e.code==='Space'){e.preventDefault();togglePlay();}if(e.key==='Escape')setMode(null);});

const scale=()=>camera.base*camera.zoom,toScreen=p=>({x:(p.x-camera.x)*scale()+width/2,y:(p.y-camera.y)*scale()+height/2}),toWorld=(x,y)=>({x:(x-width/2)/scale()+camera.x,y:(y-height/2)/scale()+camera.y});
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);width=rect.width;height=rect.height;canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);camera.base=Math.min((width-35)/WORLD.width,(height-58)/WORLD.height);}
new ResizeObserver(resize).observe(canvas);
let pointer=null;
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;const r=canvas.getBoundingClientRect();pointer={id:e.pointerId,x:e.clientX-r.left,y:e.clientY-r.top,cx:camera.x,cy:camera.y,moved:false};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,p=toWorld(x,y);$('#coordinates').textContent=`X ${p.x.toFixed(1)}   Y ${p.y.toFixed(1)} nm`;if(pointer&&!mode){const dx=x-pointer.x,dy=y-pointer.y;if(Math.hypot(dx,dy)>5)pointer.moved=true;if(pointer.moved){camera.x=pointer.cx-dx/scale();camera.y=pointer.cy-dy/scale();canvas.style.cursor='grabbing';}}});
canvas.addEventListener('pointerup',e=>{if(!pointer)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,p=toWorld(x,y);if(!pointer.moved){if(mode?.kind==='deploy'){const a=addUnit(state,mode.type,deploySide,p);if(result(a,'单位已部署')){selected=a.unit.id;tab=deploySide==='blue'?'fleet':'contacts';$('#inspector').scrollTop=0;setMode(null);renderUI();}}else if(mode?.kind==='route'){if(result(setRoute(state,selected,p,e.shiftKey),'航点已设定')&&!e.shiftKey)setMode(null);}else{const own=state.units.filter(u=>u.side==='blue').find(u=>distance(toScreen(u),{x,y})<18),c=visibleContacts(state).find(c=>distance(toScreen(c),{x,y})<18);if(own){selected=own.id;tab='fleet';$('#inspector-body').scrollTop=0;setWidgetOpen('inspector',true);}else if(c){target=c.id;setWidgetOpen('inspector',true);}lastInspector='';renderUI();}}pointer=null;canvas.style.cursor=mode?'crosshair':'default';});
canvas.addEventListener('pointercancel',()=>{pointer=null;});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();if(mode)setMode(null);else{const r=canvas.getBoundingClientRect();result(setRoute(state,selected,toWorld(e.clientX-r.left,e.clientY-r.top),e.shiftKey),'航点已设定');}});
canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,before=toWorld(x,y);camera.zoom=Math.max(.65,Math.min(5,camera.zoom*Math.exp(-e.deltaY*.0015)));const after=toWorld(x,y);camera.x+=before.x-after.x;camera.y+=before.y-after.y;},{passive:false});

function path(points,close=false){ctx.beginPath();points.forEach((p,i)=>{const a=toScreen(Array.isArray(p)?{x:p[0],y:p[1]}:p);i?ctx.lineTo(a.x,a.y):ctx.moveTo(a.x,a.y);});if(close)ctx.closePath();}
function label(text,x,y,color='#6b8b9c',size=9){ctx.fillStyle=color;ctx.font=`${size}px "IBM Plex Mono",monospace`;ctx.fillText(text,x,y);}
function worldLabel(text,p,color,size=10){const a=toScreen(p);label(text,a.x,a.y,color,size);}
function ring(u,range,color,dash=[]){const a=toScreen(u);ctx.beginPath();ctx.arc(a.x,a.y,range*scale(),0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=1;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([]);}
function drawMap(now){
  ctx.clearRect(0,0,width,height);const grad=ctx.createLinearGradient(0,0,width,height);grad.addColorStop(0,'#112630');grad.addColorStop(1,'#0c202d');ctx.fillStyle=grad;ctx.fillRect(0,0,width,height);
  for(const poly of LAND){const center={x:poly.reduce((s,p)=>s+p[0],0)/poly.length,y:poly.reduce((s,p)=>s+p[1],0)/poly.length};for(let k=4;k>=1;k--){const expanded=poly.map(p=>[center.x+(p[0]-center.x)*(1+k*.13),center.y+(p[1]-center.y)*(1+k*.13)]);path(expanded,true);ctx.strokeStyle=`rgba(51,91,108,${.13+k*.015})`;ctx.lineWidth=1;ctx.stroke();}}
  if(layers.grid){ctx.strokeStyle='#72909d0f';ctx.lineWidth=1;for(let x=0;x<=240;x+=20){path([{x,y:0},{x,y:170}]);ctx.stroke();const p=toScreen({x,y:0});if(p.x>10&&p.x<width-10)label(String(x).padStart(3,'0'),p.x+4,Math.max(80,p.y+12),'#587889',8);}for(let y=0;y<=170;y+=20){path([{x:0,y},{x:240,y}]);ctx.stroke();const p=toScreen({x:0,y});if(p.y>80&&p.y<height-30)label(String(y).padStart(3,'0'),Math.max(10,p.x+4),p.y-4,'#587889',8);}}
  if(state.phase==='setup'&&state.scenario!=='sandbox'){path([{x:24,y:55},{x:115,y:55},{x:115,y:158},{x:24,y:158}],true);ctx.fillStyle='#6cbba607';ctx.fill();ctx.setLineDash([4,6]);ctx.strokeStyle='#80cbb825';ctx.stroke();ctx.setLineDash([]);worldLabel('BLUE DEPLOYMENT',{x:27,y:151},'#598879',8);}
  for(const poly of LAND){path(poly,true);ctx.fillStyle='#213641';ctx.fill();ctx.strokeStyle='#45606a';ctx.lineWidth=1;ctx.stroke();const center={x:poly.reduce((s,p)=>s+p[0],0)/poly.length,y:poly.reduce((s,p)=>s+p[1],0)/poly.length};path(poly.map(p=>[center.x+(p[0]-center.x)*.8,center.y+(p[1]-center.y)*.8]),true);ctx.strokeStyle='#425d652b';ctx.stroke();}
  worldLabel('苍 岬 群 岛',{x:122,y:27},'#8a9ca4',10);worldLabel('西 岸',{x:7,y:40},'#788e98',10);worldLabel('东部浅滩',{x:218,y:153},'#788e98',9);worldLabel('NORTH PASSAGE',{x:168,y:38},'#3f6579',10);worldLabel('深 蓝 海 峡',{x:111,y:79},'#3f6275',13);worldLabel('SOUTHERN APPROACH',{x:101,y:158},'#3f6579',9);
  const u=unitById(state,selected);if(layers.sensors&&u?.hp>0){const t=TYPES[u.type],weather=state.weather==='storm'?.78:1;const a=toScreen(u);if(u.radar&&t.radar){const range=t.radar*weather;ring(u,range,'#75cbb83b',[5,6]);ring(u,range/2,'#75cbb813');ctx.save();ctx.translate(a.x,a.y);ctx.rotate(now/7000);const g=ctx.createConicGradient(0,0,0);g.addColorStop(0,'#80cbb827');g.addColorStop(.055,'#80cbb807');g.addColorStop(.11,'#80cbb800');g.addColorStop(1,'#80cbb800');ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,range*scale(),0,Math.PI*2);ctx.fill();ctx.restore();const p=toScreen({x:u.x,y:u.y-range});label(`RADAR ${range.toFixed(0)} nm`,p.x+6,p.y+13,'#659b8c',8);}if(u.sonar&&t.sonar)ring(u,t.sonar*weather*(u.speed>18?.45:u.speed>10?.75:1),'#7baad871',[2,4]);}
  for(const v of state.units.filter(u=>u.side==='blue'&&u.hp>0)){if(layers.trails&&v.trail.length>1){path(v.trail);ctx.strokeStyle='#80cbb82b';ctx.lineWidth=1;ctx.stroke();}if(v.route.length){path([v,...v.route]);ctx.strokeStyle=v.id===selected?'#9bceb78c':'#80cbb832';ctx.lineWidth=1;ctx.setLineDash([5,5]);ctx.stroke();ctx.setLineDash([]);if(v.id===selected)for(const [i,p] of v.route.entries()){const a=toScreen(p);ctx.strokeStyle='#9bceb7';ctx.strokeRect(a.x-3,a.y-3,6,6);label(String(i+1),a.x+8,a.y+3,'#9bceb7',9);}}if(v.leader){const leader=unitById(state,v.leader);if(leader?.hp>0){path([v,leader]);ctx.strokeStyle='#80cbb820';ctx.setLineDash([2,5]);ctx.stroke();ctx.setLineDash([]);}}}
  for(const c of visibleContacts(state)){const a=toScreen(c);ctx.save();ctx.translate(a.x,a.y);ctx.strokeStyle=c.stale?'#9c7d75':'#e88480';ctx.fillStyle='#e8848008';ctx.lineWidth=1.4;if(c.quality==='bearing'){ctx.setLineDash([3,4]);ctx.beginPath();ctx.arc(0,0,6*scale(),0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);}ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(10,0);ctx.lineTo(0,10);ctx.lineTo(-10,0);ctx.closePath();ctx.fill();ctx.stroke();if(c.domain==='air'){ctx.beginPath();ctx.moveTo(-5,3);ctx.lineTo(0,-3);ctx.lineTo(5,3);ctx.stroke();}if(c.domain==='sub'){ctx.beginPath();ctx.moveTo(-4,2);ctx.lineTo(4,2);ctx.stroke();}if(target===c.id){ctx.strokeStyle='#e9a39c';ctx.strokeRect(-15,-15,30,30);}ctx.restore();label(c.label,a.x+15,a.y-3,c.stale?'#8d827d':'#ce9b95',9);label(c.stale?'LOST':c.quality==='bearing'?'ESM / EST':'TRACK',a.x+15,a.y+11,'#826967',7);}
  for(const v of state.units.filter(u=>u.side==='blue'||state.phase==='setup'&&state.scenario==='sandbox'))drawUnit(v);
  for(const m of state.missiles){if(m.side==='red'&&!state.units.some(u=>u.side==='blue'&&u.hp>0&&(distance(u,m)<7||u.radar&&distance(u,m)<TYPES[u.type].radar)))continue;const a=toScreen(m);if(m.trail.length){path(m.trail);ctx.strokeStyle=m.side==='blue'?'#9ddac077':'#e8848077';ctx.lineWidth=1.5;ctx.stroke();}ctx.save();ctx.translate(a.x,a.y);ctx.rotate(m.heading*Math.PI/180);ctx.strokeStyle=m.side==='blue'?'#c1ebcc':'#f6b19d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,5);ctx.lineTo(0,-5);ctx.moveTo(-3,-1);ctx.lineTo(0,-5);ctx.lineTo(3,-1);ctx.stroke();ctx.restore();label(WEAPONS[m.weapon].short,a.x+7,a.y+3,m.side==='blue'?'#9cc8b1':'#e2a298',7);}
  for(const e of state.effects){const a=toScreen(e),age=state.time-e.time;ctx.beginPath();ctx.arc(a.x,a.y,5+age*1.2,0,Math.PI*2);ctx.strokeStyle=e.kind==='hit'?`rgba(236,178,104,${Math.max(0,1-age/18)})`:`rgba(147,205,185,${Math.max(0,1-age/18)})`;ctx.lineWidth=2;ctx.stroke();}
  // 罗盘与海里比例尺固定在屏幕位置，缩放后仍可读。
  ctx.save();ctx.translate(width-41,91);label('N',-3,-16,'#88a6b5',10);ctx.strokeStyle='#7291a0';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(-5,8);ctx.lineTo(0,4);ctx.lineTo(5,8);ctx.closePath();ctx.stroke();ctx.restore();
  const barNm=scale()>6?10:scale()>3?20:40,bar=barNm*scale();ctx.strokeStyle='#587a8d';ctx.beginPath();ctx.moveTo(24,height-60);ctx.lineTo(24+bar,height-60);ctx.moveTo(24,height-64);ctx.lineTo(24,height-56);ctx.moveTo(24+bar,height-64);ctx.lineTo(24+bar,height-56);ctx.stroke();label(`${barNm} nm`,25,height-70,'#7292a3',8);
  drawRadar(now);
}
function drawUnit(u){const a=toScreen(u),t=TYPES[u.type];ctx.save();ctx.translate(a.x,a.y);ctx.strokeStyle=u.hp>0?(u.side==='blue'?'#8cd3bd':'#e88480'):'#526975';ctx.fillStyle=u.id===selected?'#80cbb81d':'#122e35';ctx.lineWidth=1.3;
  if(u.hp<=0){ctx.beginPath();ctx.moveTo(-5,-5);ctx.lineTo(5,5);ctx.moveTo(5,-5);ctx.lineTo(-5,5);ctx.stroke();ctx.restore();return;}
  if(u.id===selected){ctx.beginPath();ctx.arc(0,0,19,0,Math.PI*2);ctx.strokeStyle='#80cbb86a';ctx.stroke();ctx.strokeStyle='#a6e3ca';}
  if(t.domain==='air'){ctx.beginPath();ctx.moveTo(-9,5);ctx.lineTo(0,-9);ctx.lineTo(9,5);ctx.moveTo(0,-9);ctx.lineTo(0,10);ctx.moveTo(-5,10);ctx.lineTo(0,7);ctx.lineTo(5,10);ctx.stroke();}else if(t.domain==='sub'){ctx.beginPath();ctx.ellipse(0,0,10,6,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(-4,9);ctx.lineTo(4,9);ctx.stroke();}else{ctx.fillRect(-7,-8,14,16);ctx.strokeRect(-7,-8,14,16);ctx.beginPath();ctx.moveTo(-4,0);ctx.lineTo(4,0);ctx.moveTo(0,-4);ctx.lineTo(0,4);ctx.stroke();}
  ctx.save();ctx.rotate(u.heading*Math.PI/180);ctx.strokeStyle='#8cd3bd66';ctx.beginPath();ctx.moveTo(0,-14);ctx.lineTo(0,-23);ctx.stroke();ctx.restore();ctx.restore();label(u.name,a.x+15,a.y-3,u.side==='red'?'#ce9b95':u.id===selected?'#c4dfd4':'#95b9af',9);label(`${t.code} / ${u.speed} kn`,a.x+15,a.y+10,'#577f80',7);
}
function drawRadar(now){const el=$('#radar-mini'),u=unitById(state,selected);if(!el||!u)return;const r=el.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);if(r.width<1||r.height<1)return;if(el.width!==Math.round(r.width*dpr)||el.height!==Math.round(r.height*dpr)){el.width=Math.round(r.width*dpr);el.height=Math.round(r.height*dpr);}const c=el.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,r.width,r.height);const cx=r.width/2,cy=r.height/2,R=Math.min(cy-8,45);c.strokeStyle='#36554b';c.lineWidth=.6;for(let i=1;i<=3;i++){c.beginPath();c.arc(cx,cy,R*i/3,0,Math.PI*2);c.stroke();}c.beginPath();c.moveTo(cx-R,cy);c.lineTo(cx+R,cy);c.moveTo(cx,cy-R);c.lineTo(cx,cy+R);c.stroke();if((u.radar||u.sonar)&&u.hp>0){const a=now/1000;c.strokeStyle='#6fbea782';c.beginPath();c.moveTo(cx,cy);c.lineTo(cx+Math.cos(a)*R,cy+Math.sin(a)*R);c.stroke();const range=Math.max(TYPES[u.type].radar,TYPES[u.type].sonar,1);for(const p of visibleContacts(state)){const d=distance(u,p);if(d>range)continue;c.fillStyle=p.stale?'#785d5b':'#e99a88';c.fillRect(cx+(p.x-u.x)/range*R-1.5,cy+(p.y-u.y)/range*R-1.5,3,3);}}c.fillStyle='#93cfb9';c.fillRect(cx-1,cy-1,2,2);c.font='8px "IBM Plex Mono",monospace';c.fillStyle='#587e75';c.fillText('LOCAL PICTURE',9,14);c.fillText(u.radar?'RADAR ON':u.sonar?'SONAR ON':'EMCON',9,r.height-9);c.fillText(`${visibleContacts(state).length} CONTACTS`,r.width-74,r.height-9);}
function frame(now){const dt=Math.min((now-lastFrame)/1000,.2);lastFrame=now;step(state,dt*timeScale);if(now-lastUI>250){renderUI();lastUI=now;}drawMap(now);requestAnimationFrame(frame);}
initializeWidgets();renderUI();resize();requestAnimationFrame(frame);
